import RectangleROI from './RectangleROI';

const Disease = {
  toAnnotation: measurement => {},
  toMeasurement: (
    csToolsEventDetail,
    displaySetService,
    CornerstoneViewportService,
    getValueTypeFromToolType,
    customizationService
  ) => {
    const { metadata, data } = csToolsEventDetail.annotation;
    if (!metadata || !data) {
      console.warn('Disease tool: Missing metadata or data');
      return null;
    }

    const measurement = RectangleROI.toMeasurement(
      csToolsEventDetail,
      displaySetService,
      CornerstoneViewportService,
      getValueTypeFromToolType,
      customizationService
    );

    // Replace getReport attribute
    const getReport = () => {
      const { columns, values } = measurement.getReport();
      values[0] = 'Cornerstone:Disease';
      return { columns, values };
    };
    measurement.getReport = getReport;

    return measurement;
  },
};

export default Disease;
